function c(t){return new Date(t).toLocaleDateString("en-In",{day:"numeric",month:"long",year:"numeric"})}function i(t){return new Date(t).toLocaleDateString("en-In",{day:"numeric",month:"short",year:"numeric"})}function m(t){return new Date(t).toLocaleDateString("en-In",{weekday:"long"})}function u(){const t=new Date,e=String(t.getDate()).padStart(2,"0"),n=String(t.getMonth()+1).padStart(2,"0"),r=t.getFullYear(),a=String(t.getHours()).padStart(2,"0"),o=String(t.getMinutes()).padStart(2,"0"),s=String(t.getSeconds()).padStart(2,"0");return`${r}-${n}-${e} ${a}:${o}:${s}`}export{m as d,u as f,c as l,i as s};
